package com.xianshuyuan.scm.order.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.xianshuyuan.scm.common.exception.BusinessException;
import com.xianshuyuan.scm.order.dto.*;
import com.xianshuyuan.scm.order.entity.*;
import com.xianshuyuan.scm.order.mapper.*;
import java.math.BigDecimal;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class AfterSalesApplicationService {
 private static final String ACTOR="SYSTEM"; private final SalesOrderMapper orders;private final SalesOrderItemMapper orderItems;private final OrderReturnMapper returns;private final OrderReturnItemMapper returnItems;private final OrderRefundMapper refunds;private final OrderOperationLogMapper logs;private final IdempotencyRecordMapper idempotency;private final ObjectMapper json;private final IdempotencyRequestHasher hasher;
 public AfterSalesApplicationService(SalesOrderMapper o,SalesOrderItemMapper oi,OrderReturnMapper r,OrderReturnItemMapper ri,OrderRefundMapper f,OrderOperationLogMapper l,IdempotencyRecordMapper i,ObjectMapper j){orders=o;orderItems=oi;returns=r;returnItems=ri;refunds=f;logs=l;idempotency=i;json=j;hasher=new IdempotencyRequestHasher(j);}
 @Transactional public long create(String key,OrderReturnCreateRequest req){return idempotent("ORDER_RETURN_CREATE",key,req,()->createInternal(req));}
 private long createInternal(OrderReturnCreateRequest req){var order=orders.selectActiveByIdForUpdate(req.orderId());if(order==null)throw new BusinessException(AfterSalesErrorCodes.ORDER_ITEM_INVALID);if(order.getStatus()!=OrderStatus.CONFIRMED)throw new BusinessException(AfterSalesErrorCodes.ORDER_NOT_CONFIRMED);var original=orderItems.selectActiveByOrderIdForUpdate(order.getId());var byId=original.stream().collect(Collectors.toMap(SalesOrderItemEntity::getId,x->x));if(req.items().stream().map(OrderReturnCreateRequest.Item::orderItemId).distinct().count()!=req.items().size())throw new BusinessException(AfterSalesErrorCodes.ORDER_ITEM_INVALID);var ids=req.items().stream().map(OrderReturnCreateRequest.Item::orderItemId).toList();var reserved=reserved(returnItems.selectReservedByOrderItemIdsForUpdate(ids));for(var item:req.items()){var source=byId.get(item.orderItemId());if(source==null||source.getActualQuantity()==null||source.getLockedUnitPrice()==null)throw new BusinessException(AfterSalesErrorCodes.ORDER_ITEM_INVALID);try{AfterSalesRules.requireWithinActual(source.getActualQuantity(),reserved.getOrDefault(source.getId(),BigDecimal.ZERO),item.requestedQuantity());}catch(AfterSalesRuleException e){throw new BusinessException(AfterSalesErrorCodes.RETURN_QUANTITY_EXCEEDED);}}
  var entity=new OrderReturnEntity();entity.setReturnNo(number("RT",returns.nextNumber()));entity.setOrderId(order.getId());entity.setCustomerId(order.getCustomerId());entity.setStatus(OrderReturnStatus.PENDING);entity.setReason(req.reason().trim());entity.setApprovedAmount(BigDecimal.ZERO.setScale(4));entity.setVersion(0);entity.setDeleted(false);entity.setCreatedBy(ACTOR);returns.insert(entity);for(var item:req.items()){var row=new OrderReturnItemEntity();row.setReturnId(entity.getId());row.setOrderItemId(item.orderItemId());row.setRequestedQuantity(item.requestedQuantity());row.setLockedUnitPrice(byId.get(item.orderItemId()).getLockedUnitPrice());row.setApprovedAmount(BigDecimal.ZERO.setScale(4));row.setVersion(0);row.setDeleted(false);row.setCreatedBy(ACTOR);returnItems.insert(row);}log(order.getId(),"RETURN_CREATED",req.reason(),null,entity);return entity.getId();}
 @Transactional public long approve(String key,long id,OrderReturnApproveRequest req){return idempotent("ORDER_RETURN_APPROVE:"+id,key,req,()->approveInternal(id,req));}
 private long approveInternal(long id,OrderReturnApproveRequest req){var entity=requireReturn(id);if(entity.getStatus()!=OrderReturnStatus.PENDING)throw new BusinessException(AfterSalesErrorCodes.RETURN_STATUS_INVALID);requireVersion(entity.getVersion(),req.version());orders.selectActiveByIdForUpdate(entity.getOrderId());var original=orderItems.selectActiveByOrderIdForUpdate(entity.getOrderId());var own=returnItems.selectByReturnId(id);var requestById=req.items().stream().collect(Collectors.toMap(OrderReturnApproveRequest.Item::returnItemId,x->x,(a,b)->{throw new BusinessException(AfterSalesErrorCodes.APPROVAL_INVALID);}));if(requestById.size()!=own.size()||!own.stream().allMatch(x->requestById.containsKey(x.getId())))throw new BusinessException(AfterSalesErrorCodes.APPROVAL_INVALID);try{AfterSalesRules.requirePositiveApproval(req.items().stream().map(OrderReturnApproveRequest.Item::approvedQuantity).toList());}catch(AfterSalesRuleException e){throw new BusinessException(AfterSalesErrorCodes.APPROVAL_INVALID);}var actual=original.stream().collect(Collectors.toMap(SalesOrderItemEntity::getId,SalesOrderItemEntity::getActualQuantity));var reserved=reserved(returnItems.selectReservedByOrderItemIdsForUpdate(own.stream().map(OrderReturnItemEntity::getOrderItemId).toList()));BigDecimal total=BigDecimal.ZERO;for(var row:own){var command=requestById.get(row.getId());requireVersion(row.getVersion(),command.version());if(command.approvedQuantity().compareTo(row.getRequestedQuantity())>0)throw new BusinessException(AfterSalesErrorCodes.APPROVAL_INVALID);var other=reserved.getOrDefault(row.getOrderItemId(),BigDecimal.ZERO).subtract(row.getRequestedQuantity());try{if(command.approvedQuantity().signum()>0)AfterSalesRules.requireWithinActual(actual.get(row.getOrderItemId()),other,command.approvedQuantity());}catch(AfterSalesRuleException e){throw new BusinessException(AfterSalesErrorCodes.RETURN_QUANTITY_EXCEEDED);}var amount=AfterSalesRules.amount(command.approvedQuantity(),row.getLockedUnitPrice());row.setApprovedQuantity(command.approvedQuantity());row.setApprovedAmount(amount);row.setUpdatedBy(ACTOR);if(returnItems.updateById(row)!=1)throw new BusinessException(AfterSalesErrorCodes.VERSION_CONFLICT);total=total.add(amount);}if(total.signum()<=0)throw new BusinessException(AfterSalesErrorCodes.APPROVAL_INVALID,"退款金额必须大于零");entity.setStatus(OrderReturnStatus.APPROVED);entity.setApprovedAmount(total);entity.setApprovedAt(OffsetDateTime.now());entity.setUpdatedBy(ACTOR);if(returns.updateById(entity)!=1)throw new BusinessException(AfterSalesErrorCodes.VERSION_CONFLICT);var refund=new OrderRefundEntity();refund.setRefundNo(number("RF",refunds.nextNumber()));refund.setReturnId(id);refund.setOrderId(entity.getOrderId());refund.setCustomerId(entity.getCustomerId());refund.setRefundAmount(total);refund.setStatus(OrderRefundStatus.PENDING);refund.setVersion(0);refund.setDeleted(false);refund.setCreatedBy(ACTOR);refunds.insert(refund);log(entity.getOrderId(),"RETURN_APPROVED",null,null,entity);log(entity.getOrderId(),"REFUND_CREATED",null,null,refund);return refund.getId();}
 @Transactional public void reject(String key,long id,OrderReturnDecisionRequest req){idempotent("ORDER_RETURN_REJECT:"+id,key,req,()->{decide(id,req,false);return id;});}
 @Transactional public void cancel(String key,long id,OrderReturnDecisionRequest req){idempotent("ORDER_RETURN_CANCEL:"+id,key,req,()->{decide(id,req,true);return id;});}
 private void decide(long id,OrderReturnDecisionRequest req,boolean cancel){var e=requireReturn(id);if(e.getStatus()!=OrderReturnStatus.PENDING)throw new BusinessException(AfterSalesErrorCodes.RETURN_STATUS_INVALID);requireVersion(e.getVersion(),req.version());e.setStatus(cancel?OrderReturnStatus.CANCELLED:OrderReturnStatus.REJECTED);e.setDecisionReason(req.reason().trim());if(cancel)e.setCancelledAt(OffsetDateTime.now());else e.setRejectedAt(OffsetDateTime.now());e.setUpdatedBy(ACTOR);if(returns.updateById(e)!=1)throw new BusinessException(AfterSalesErrorCodes.VERSION_CONFLICT);log(e.getOrderId(),cancel?"RETURN_CANCELLED":"RETURN_REJECTED",req.reason(),null,e);}
 @Transactional public void completeRefund(String key,long id,OrderRefundCompleteRequest req){idempotent("ORDER_REFUND_COMPLETE:"+id,key,req,()->{var e=refunds.selectActiveByIdForUpdate(id);if(e==null)throw new BusinessException(AfterSalesErrorCodes.REFUND_NOT_FOUND);if(e.getStatus()!=OrderRefundStatus.PENDING)throw new BusinessException(AfterSalesErrorCodes.REFUND_STATUS_INVALID);requireVersion(e.getVersion(),req.version());e.setStatus(OrderRefundStatus.COMPLETED);e.setExternalReference(blankToNull(req.externalReference()));e.setCompletedAt(OffsetDateTime.now());e.setUpdatedBy(ACTOR);try{if(refunds.updateById(e)!=1)throw new BusinessException(AfterSalesErrorCodes.VERSION_CONFLICT);}catch(DataIntegrityViolationException x){throw new BusinessException(AfterSalesErrorCodes.VERSION_CONFLICT,"外部退款凭证已存在");}log(e.getOrderId(),"REFUND_COMPLETED",null,null,e);return id;});}
 private OrderReturnEntity requireReturn(long id){var e=returns.selectActiveByIdForUpdate(id);if(e==null)throw new BusinessException(AfterSalesErrorCodes.RETURN_NOT_FOUND);return e;}private void requireVersion(Integer actual,Integer expected){if(!Objects.equals(actual,expected))throw new BusinessException(AfterSalesErrorCodes.VERSION_CONFLICT);}private Map<Long,BigDecimal> reserved(List<OrderReturnItemEntity> rows){var result=new HashMap<Long,BigDecimal>();for(var r:rows){var q=r.getApprovedQuantity()!=null?r.getApprovedQuantity():r.getRequestedQuantity();result.merge(r.getOrderItemId(),q,BigDecimal::add);}return result;}
 private long idempotent(String scope,String key,Object request,Supplier<Long> action){if(key==null||key.isBlank())throw new BusinessException(AfterSalesErrorCodes.IDEMPOTENCY_REQUIRED);String normalized=key.trim(),hash=hasher.hash(request);var existing=idempotency.selectActiveByScopeAndKeyForUpdate(scope,normalized);if(existing!=null){IdempotencyGuard.requireMatching(existing.getRequestHash(),hash);return existing.getResultId();}long result=action.get();var record=new IdempotencyRecordEntity();record.setOperationScope(scope);record.setIdempotencyKey(normalized);record.setRequestHash(hash);record.setResultType("LONG");record.setResultId(result);record.setVersion(0);record.setDeleted(false);record.setCreatedBy(ACTOR);idempotency.insert(record);return result;}
 private void log(long orderId,String type,String reason,Object before,Object after){var l=new OrderOperationLogEntity();l.setOrderId(orderId);l.setOperationType(type);l.setOperator(ACTOR);l.setReason(blankToNull(reason));l.setBeforeData(before==null?null:json.valueToTree(before));l.setAfterData(after==null?null:json.valueToTree(after));l.setCreatedBy(ACTOR);logs.insert(l);}private String number(String prefix,long sequence){return prefix+LocalDate.now().format(DateTimeFormatter.BASIC_ISO_DATE)+String.format("%06d",sequence);}private String blankToNull(String value){return value==null||value.isBlank()?null:value.trim();}
}
